const out=[];
for(const [i,item] of $input.all().entries()){
 const m=item.json.message;
 if(!m || m.chat?.type!=='private' || m.from?.is_bot || m.chat?.id==null || m.message_id==null) continue;
 const texto=typeof m.text==='string'?m.text.trim():'';
 out.push({json:{chatId:String(m.chat.id),messageId:String(m.message_id),texto,tipo:texto?'texto':'sin_texto'},pairedItem:{item:i}});
}
return out;

const base=$('Preparar mensaje').item.json;
let d;
try{
 const raw=$json.output;
 d=typeof raw==='object' && raw!==null?raw:JSON.parse(String(raw).replace(/^\x60\x60\x60(?:json)?\s*/i,'').replace(/\s*\x60\x60\x60$/,'').trim());
}catch{}
const valid=!!(d && ['responder','pedir_aclaracion','recomendar_asesor'].includes(d.accion) && typeof d.respuesta==='string' && d.respuesta.trim() && d.respuesta.length<=1200 && typeof d.motivo==='string');
if(!valid) d={accion:'recomendar_asesor',respuesta:'No pude resolver tu consulta automáticamente. Podés consultar el catálogo en https://pimesa.com.ar o comunicarte con un asesor de PIME.',motivo:'Error del agente o respuesta inválida'};
const respuesta=base.tipo==='sin_texto'?'Por ahora puedo procesar mensajes de texto. ¿Podés escribir tu consulta?':d.respuesta.trim();
return [{json:{chatId:base.chatId,messageId:base.messageId,accion:base.tipo==='sin_texto'?'pedir_aclaracion':d.accion,respuesta,motivo:d.motivo.slice(0,500),valid}}];
